CREATE DATABASE IF NOT EXISTS vastra_mart CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vastra_mart;
DROP TABLE IF EXISTS feedback,order_items,orders,products,categories,customers,admins;
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(160) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL);
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,phone VARCHAR(30),password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,icon VARCHAR(20),slug VARCHAR(150));
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) UNIQUE NOT NULL,category_id INT NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,stock INT NOT NULL DEFAULT 0,image TEXT,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,customer_name VARCHAR(120),phone VARCHAR(30),address TEXT,payment_method VARCHAR(60),total DECIMAL(12,2),status VARCHAR(40) DEFAULT "Placed",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_code VARCHAR(20),product_name VARCHAR(180),qty INT,price DECIMAL(10,2),subtotal DECIMAL(12,2),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE feedback (id INT AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(120),rating TINYINT,text TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
